from fastapi import APIRouter, Depends
from fastapi.responses import HTMLResponse

from app.api.dashboard_session import require_business_auth


router = APIRouter()

HTML = r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>서비스·연결·요금 관리 · AI Business OS</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#172033;font-family:Inter,Pretendard,"Noto Sans KR",system-ui,sans-serif}.service-main{max-width:1440px;margin:auto;padding:26px}.top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:18px}.top h1{margin:4px 0 5px;font-size:27px}.muted{color:#68768a;font-size:12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid #c8d2df;background:#fff;color:#25344a;border-radius:9px;padding:9px 12px;cursor:pointer;font:inherit;font-weight:700;text-decoration:none}.btn.primary{background:#2763dc;border-color:#2763dc;color:#fff}.btn:disabled{opacity:.55;cursor:default}.status{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:999px;font-size:11px;font-weight:800;white-space:nowrap}.status:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.normal,.confirmed{background:#e6f6ee;color:#17734a}.attention{background:#fdebea;color:#b42318}.manual,.manual_check{background:#edf1f7;color:#526176}.not_connected{background:#fff4d8;color:#8a5a00}.not_applicable{background:#edf1f7;color:#526176}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:15px}.kpi,.panel{background:#fff;border:1px solid #dce3ec;border-radius:12px}.kpi{padding:14px}.kpi-label{font-size:12px;color:#68768a;margin-bottom:8px}.kpi-value{font-size:23px;font-weight:800}.kpi-foot{font-size:11px;color:#68768a;margin-top:5px}.layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(290px,.8fr);gap:14px}.panel{padding:16px;min-width:0}.panel-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:13px}.panel h2{font-size:17px;margin:0}.panel h3{font-size:14px;margin:15px 0 8px}.budget-line{display:flex;justify-content:space-between;gap:12px;font-size:12px;margin-bottom:7px}.track{height:9px;background:#e8edf4;border-radius:999px;overflow:hidden;margin-bottom:14px}.fill{height:100%;width:0;background:#2763dc;border-radius:999px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px;min-width:800px}th{text-align:left;color:#68768a;padding:9px 8px;border-bottom:1px solid #dce3ec;white-space:nowrap}td{padding:10px 8px;border-bottom:1px solid #edf0f5;vertical-align:middle}tbody tr{cursor:pointer}tbody tr:hover,tbody tr.selected{background:#f2f6ff}.service-name{font-weight:800}.service-purpose{font-size:10px;color:#78869a;margin-top:3px}.side-panels{display:grid;gap:14px;align-content:start}.detail{display:grid;gap:9px}.detail-row{display:flex;justify-content:space-between;gap:12px;font-size:12px;padding-bottom:8px;border-bottom:1px solid #edf0f5}.detail-row span:first-child{color:#68768a}.detail-row strong{text-align:right}.impact{display:flex;gap:6px;flex-wrap:wrap}.impact span{font-size:10px;background:#edf3ff;color:#2258ad;padding:5px 7px;border-radius:999px}.security{padding:12px;border-left:4px solid #2763dc;background:#f2f6ff;font-size:12px;line-height:1.6}.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field{display:grid;gap:5px;font-size:12px}.field.full{grid-column:1/-1}.field input,.field select,.field textarea{width:100%;border:1px solid #c8d2df;border-radius:8px;padding:9px;font:inherit}.field textarea{min-height:70px;resize:vertical}.error{color:#b42318;font-size:12px}.official-links{display:flex;gap:7px;flex-wrap:wrap}.official-links a[hidden]{display:none}.loading{padding:50px;text-align:center;color:#68768a}@media(max-width:1050px){.layout{grid-template-columns:1fr}.side-panels{grid-template-columns:1fr 1fr}}@media(max-width:760px){.service-main{padding:14px}.top{display:block}.top .actions{margin-top:12px}.kpis{grid-template-columns:repeat(2,1fr)}.side-panels{grid-template-columns:1fr}.edit-grid{grid-template-columns:1fr}.field.full{grid-column:auto}}
</style></head><body><main class="service-main"><header class="top"><div><div class="muted">운영 › 서비스·연결·요금 관리</div><h1>서비스·연결·요금 관리</h1><div class="muted">연결·인증·결제·사용량과 영향을 한곳에서 확인합니다.</div></div><div class="actions"><button class="btn" id="refresh">↻ 전체 상태 확인</button><a class="btn" href="/dashboard">실행 기록</a></div></header><section class="kpis" aria-label="전체 현황"><div class="kpi"><div class="kpi-label">등록 서비스</div><div class="kpi-value" id="serviceCount">-</div><div class="kpi-foot" id="serviceState">불러오는 중</div></div><div class="kpi"><div class="kpi-label">이번 달 기록 비용</div><div class="kpi-value" id="monthCost">-</div><div class="kpi-foot">자동 또는 수동 입력 합계</div></div><div class="kpi"><div class="kpi-label">결제·인증 확인</div><div class="kpi-value" id="attentionCount">-</div><div class="kpi-foot">미연결·주의 서비스 포함</div></div><div class="kpi"><div class="kpi-label">통합 예산 사용률</div><div class="kpi-value" id="budgetPercent">-</div><div class="kpi-foot" id="budgetCaption">예산을 등록해 주세요</div></div></section><div class="layout"><section class="panel"><div class="panel-head"><div><h2>서비스 현황</h2><div class="muted">서비스를 선택하면 관리정보와 연결 기능이 표시됩니다.</div></div><span class="status normal" id="checkedAt">상태 확인 중</span></div><div class="budget-line"><span>월 통합 예산</span><strong id="budgetLine">-</strong></div><div class="track" role="progressbar" aria-label="월 통합 예산 사용률" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div class="fill" id="budgetFill"></div></div><div class="table-wrap"><table><thead><tr><th>서비스</th><th>연결·인증</th><th>결제 상태</th><th>이번 달</th><th>월 예산</th><th>갱신일</th></tr></thead><tbody id="serviceRows"><tr><td colspan="6" class="loading">서비스 상태를 불러오고 있습니다.</td></tr></tbody></table></div></section><aside class="side-panels"><section class="panel"><div class="panel-head"><div><h2 id="detailName">서비스 상세</h2><div class="muted" id="detailPurpose">서비스를 선택하세요.</div></div><span class="status manual" id="detailStatus">확인 전</span></div><div class="detail" id="detailRows"></div><h3>연결된 기능</h3><div class="impact" id="features"></div><h3>공식 관리 바로가기</h3><div class="official-links"><a class="btn" id="managementLink" target="_blank" rel="noopener noreferrer">서비스 관리</a><a class="btn" id="billingLink" target="_blank" rel="noopener noreferrer">결제 관리</a><a class="btn" id="usageLink" target="_blank" rel="noopener noreferrer">사용량 확인</a><a class="btn primary" id="reauthLink">재인증</a></div></section><section class="panel"><div class="panel-head"><div><h2>관리정보 입력</h2><div class="muted">결제·예산 정보가 자동 제공되지 않는 서비스에 사용합니다.</div></div></div><form id="settingForm"><div class="edit-grid"><label class="field"><span>요금제</span><input id="planName" maxlength="160" placeholder="예: 사용량 과금"></label><label class="field"><span>결제 상태</span><select id="billingStatus"><option value="manual_check">수동 확인 필요</option><option value="confirmed">정상 확인</option><option value="attention">결제 확인 필요</option><option value="not_applicable">해당 없음</option></select></label><label class="field"><span>이번 달 비용(원)</span><input id="monthCostInput" type="number" min="0" max="1000000000"></label><label class="field"><span>월 예산(원)</span><input id="monthBudgetInput" type="number" min="0" max="1000000000"></label><label class="field"><span>갱신·결제 예정일</span><input id="renewalDate" type="date"></label><label class="field"><span>사용량 메모</span><input id="usageSummary" maxlength="240" placeholder="예: 저장공간 41%"></label><label class="field full"><span>운영 메모</span><textarea id="note" maxlength="1000" placeholder="비밀번호·카드번호·API 키·토큰은 입력하지 마세요."></textarea></label></div><p class="error" id="formError" role="alert"></p><div class="actions"><button class="btn primary" id="saveSetting" type="submit">관리정보 저장</button></div></form></section><section class="security"><strong>안전 경계</strong><br>비밀번호·카드번호·API 키 원문은 저장하거나 표시하지 않습니다. 결제와 요금제 변경은 Agent가 수행하지 않으며, 공식 서비스 화면에서 사용자가 직접 완료합니다.</section></aside></div></main><script>
(function(){const tenant='__legacy__',rows=document.getElementById('serviceRows');let data=[],selected='';const billingLabels={confirmed:'정상 확인',attention:'결제 확인 필요',manual_check:'수동 확인',not_applicable:'해당 없음'},connectionLabels={normal:'정상',attention:'주의',manual:'수동 확인',not_connected:'미연결'};function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function won(v){return v===null||v===undefined?'미등록':Number(v).toLocaleString('ko-KR')+'원'}function status(label,state){return `<span class="status ${esc(state)}">${esc(label)}</span>`}function setLink(id,url){const a=document.getElementById(id);if(url){a.href=url;a.hidden=false;if(url.startsWith('/')){a.removeAttribute('target');a.removeAttribute('rel')}else{a.target='_blank';a.rel='noopener noreferrer'}}else{a.hidden=true;a.removeAttribute('href')}}async function load(){document.getElementById('refresh').disabled=true;try{const r=await fetch('/api/v1/service-management/services?tenant_id='+encodeURIComponent(tenant),{credentials:'same-origin'});if(!r.ok)throw Error('서비스 상태를 불러오지 못했습니다.');const d=await r.json();data=d.services;const s=d.summary;document.getElementById('serviceCount').textContent=s.service_count;document.getElementById('attentionCount').textContent=s.attention_count;document.getElementById('monthCost').textContent=won(s.current_month_cost_krw);document.getElementById('budgetPercent').textContent=s.budget_usage_percent===null?'미등록':s.budget_usage_percent+'%';document.getElementById('budgetCaption').textContent=s.monthly_budget_krw?`예산 ${won(s.monthly_budget_krw)}`:'등록된 월 예산 없음';document.getElementById('serviceState').textContent=`정상 ${data.filter(x=>x.connection_status==='normal').length} · 확인 필요 ${s.attention_count}`;document.getElementById('budgetLine').textContent=`${won(s.current_month_cost_krw)} / ${won(s.monthly_budget_krw)}`;const pct=Math.min(100,s.budget_usage_percent||0);document.getElementById('budgetFill').style.width=pct+'%';document.querySelector('.track').setAttribute('aria-valuenow',String(pct));document.getElementById('checkedAt').textContent='방금 상태 확인';rows.innerHTML=data.map(x=>`<tr data-code="${esc(x.code)}"><td><div class="service-name">${esc(x.name)}</div><div class="service-purpose">${esc(x.purpose)}</div></td><td>${status(x.connection_label,x.connection_status)}</td><td>${status(billingLabels[x.billing_status]||x.billing_status,x.billing_status)}</td><td>${esc(won(x.current_month_cost_krw))}</td><td>${esc(won(x.monthly_budget_krw))}</td><td>${esc(x.renewal_date||'미등록')}</td></tr>`).join('');select(selected&&data.some(x=>x.code===selected)?selected:data[0].code)}catch(e){rows.innerHTML=`<tr><td colspan="6" class="error">${esc(e.message)}</td></tr>`}finally{document.getElementById('refresh').disabled=false}}function select(code){selected=code;const x=data.find(item=>item.code===code);if(!x)return;rows.querySelectorAll('tr').forEach(r=>r.classList.toggle('selected',r.dataset.code===code));document.getElementById('detailName').textContent=x.name;document.getElementById('detailPurpose').textContent=x.purpose;const badge=document.getElementById('detailStatus');badge.className='status '+x.connection_status;badge.textContent=x.connection_label;document.getElementById('detailRows').innerHTML=[['인증 상태',x.auth_label],['확인 방식',x.check_method],['요금제',x.plan_name||'미등록'],['결제 상태',billingLabels[x.billing_status]],['이번 달 비용',won(x.current_month_cost_krw)],['월 예산',won(x.monthly_budget_krw)],['갱신일',x.renewal_date||'미등록'],['사용량',x.usage_summary||'미등록'],['마지막 수정',x.updated_at||'미등록']].map(([a,b])=>`<div class="detail-row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('');document.getElementById('features').innerHTML=x.features.map(f=>`<span>${esc(f)}</span>`).join('');setLink('managementLink',x.management_url);setLink('billingLink',x.billing_url);setLink('usageLink',x.usage_url);setLink('reauthLink',x.reauth_url);document.getElementById('planName').value=x.plan_name||'';document.getElementById('billingStatus').value=x.billing_status;document.getElementById('monthCostInput').value=x.current_month_cost_krw??'';document.getElementById('monthBudgetInput').value=x.monthly_budget_krw??'';document.getElementById('renewalDate').value=x.renewal_date||'';document.getElementById('usageSummary').value=x.usage_summary||'';document.getElementById('note').value=x.note||'';document.getElementById('formError').textContent=''}rows.onclick=e=>{const row=e.target.closest('tr[data-code]');if(row)select(row.dataset.code)};document.getElementById('refresh').onclick=load;document.getElementById('settingForm').onsubmit=async e=>{e.preventDefault();if(!selected)return;const error=document.getElementById('formError'),button=document.getElementById('saveSetting');button.disabled=true;error.textContent='';const number=id=>{const value=document.getElementById(id).value;return value===''?null:Number(value)};const body={plan_name:document.getElementById('planName').value||null,billing_status:document.getElementById('billingStatus').value,current_month_cost_krw:number('monthCostInput'),monthly_budget_krw:number('monthBudgetInput'),renewal_date:document.getElementById('renewalDate').value||null,usage_summary:document.getElementById('usageSummary').value||null,note:document.getElementById('note').value||null,updated_by:'dashboard-user'};try{const r=await fetch(`/api/v1/service-management/services/${encodeURIComponent(selected)}?tenant_id=${encodeURIComponent(tenant)}`,{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:(d.detail?.[0]?.msg||'저장하지 못했습니다.'));await load()}catch(err){error.textContent=err.message}finally{button.disabled=false}};load()})();
</script></body></html>'''


@router.get(
    "/service-management",
    response_class=HTMLResponse,
    include_in_schema=False,
    dependencies=[Depends(require_business_auth)],
)
def service_management_page():
    return HTMLResponse(HTML, headers={"Cache-Control": "no-store"})
